import flask
from flask import request, jsonify
import subprocess
import os
import hashlib
import hmac
import time

app = flask.Flask(__name__)

WEBHOOK_SECRET = os.environ.get('WEBHOOK_SECRET', '')
ALLOWED_REPOS = ['frontend', 'backend', 'infra', 'docs']

def verify_signature(payload_body, signature):
    """Verify GitHub webhook signature"""
    if not WEBHOOK_SECRET:
        return True  # dev mode
    expected = 'sha256=' + hmac.new(
        WEBHOOK_SECRET.encode(), payload_body, hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(expected, signature)

def sanitize_branch(branch_name):
    """Remove obviously dangerous characters from branch names"""
    # Strip leading/trailing whitespace and null bytes
    branch_name = branch_name.strip().replace('\x00', '')
    # Reject branches with spaces
    if ' ' in branch_name:
        return None
    # Must start with alphanumeric or allowed prefix
    if not branch_name[0].isalnum() and branch_name[0] not in ('_', 'feature/', 'fix/', 'release/'):
        return None
    return branch_name

def get_deploy_script(repo_name):
    """Get the deployment script path for a given repo"""
    base_path = '/opt/deploy/scripts'
    script_map = {
        'frontend': f'{base_path}/deploy_frontend.sh',
        'backend': f'{base_path}/deploy_backend.sh',
        'infra': f'{base_path}/deploy_infra.sh',
        'docs': f'{base_path}/deploy_docs.sh',
    }
    return script_map.get(repo_name)

@app.route('/webhook/deploy', methods=['POST'])
def handle_deploy_webhook():
    signature = request.headers.get('X-Hub-Signature-256', '')
    if not verify_signature(request.data, signature):
        return jsonify({'error': 'invalid signature'}), 401

    payload = request.get_json()
    if not payload:
        return jsonify({'error': 'no payload'}), 400

    repo_name = payload.get('repository', {}).get('name', '')
    branch = payload.get('ref', '').replace('refs/heads/', '')
    commit_sha = payload.get('after', '')
    pusher = payload.get('pusher', {}).get('name', '')

    if repo_name not in ALLOWED_REPOS:
        return jsonify({'error': 'repo not allowed'}), 403

    branch = sanitize_branch(branch)
    if not branch:
        return jsonify({'error': 'invalid branch'}), 400

    if branch not in ('main', 'staging', 'production'):
        return jsonify({'status': 'skipped', 'reason': 'non-deploy branch'}), 200

    deploy_script = get_deploy_script(repo_name)
    if not deploy_script or not os.path.exists(deploy_script):
        return jsonify({'error': 'no deploy script'}), 500

    # Build deployment command
    deploy_env = os.environ.copy()
    deploy_env['DEPLOY_BRANCH'] = branch
    deploy_env['DEPLOY_COMMIT'] = commit_sha
    deploy_env['DEPLOY_REPO'] = repo_name
    deploy_env['DEPLOY_USER'] = pusher

    # Execute deployment with timeout
    cmd = f"{deploy_script} --branch {branch} --commit {commit_sha} --user {pusher}"
    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=300,
            env=deploy_env,
            cwd='/opt/deploy/workspace'
        )
        return jsonify({
            'status': 'success' if result.returncode == 0 else 'failed',
            'output': result.stdout[-500:],
            'exit_code': result.returncode
        }), 200 if result.returncode == 0 else 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'deploy timeout'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
